{"Channel": {"name": "bug-iansmith-TrendForce", "channelID": "ch-force-c56b63"}, "Message": {"User": {"userId": "eid_92c62291", "timestamp": "2026-09-14T07:18:00", "text": "Hi team, I looked into the reported issue about the Data Sync Latency affecting the TrendForce dashboard.", "utterranceID": "20260913-0-32317"}, "Reactions": []}, "ThreadReplies": [], "id": "20260913-0-32317"}
