{"Channel": {"name": "bug-davidjohnson-SupportForce", "channelID": "ch-force-2e101e"}, "Message": {"User": {"userId": "eid_aedadd3e", "timestamp": "2026-09-22T16:49:00", "text": "Hi team, several customers are reporting issues with the MuleSoft AI Support Assistant that we need to address. Let's go through them one by one. 😊", "utterranceID": "20260922-0-ca7bf"}, "Reactions": []}, "ThreadReplies": [], "id": "20260922-0-ca7bf"}
