{"Channel": {"name": "bug-hannahsmith-CollaborateForce", "channelID": "ch-force-1162dc"}, "Message": {"User": {"userId": "eid_16935c12", "timestamp": "2027-03-04T17:28:00", "text": "Hi team, several customers are reporting issues with CollaborateForce that we need to address. Let's go through them one by one. 😊", "utterranceID": "20270304-0-b2b15"}, "Reactions": []}, "ThreadReplies": [], "id": "20270304-0-b2b15"}
